package tools; import policy.*;import core.Diagnostics; public final class PolicyAudit{public static void main(String[] args){try{PolicyDocument doc=new PolicyParser().parseText(CliSupport.readText(args)).orNull();Diagnostics d=new PolicyValidator().validate(doc);RuleOrderingAnalyzer a=new RuleOrderingAnalyzer();System.out.println(new PolicySummary().summarize(doc));System.out.print(d.render());for(DuplicateFinding f:a.duplicates(doc))System.out.println(f);for(ShadowFinding f:a.shadowed(doc))System.out.println(f);}catch(Exception e){CliSupport.exitOnError(e);}}}
